"""Cuaderno del estudiante, 1.º medio Lengua y Literatura, OA 18 (ortografía y puntuación para facilitar la comprensión).

Cada ejercicio trae la palabra o la oración que necesita. Las reglas siguen la ortografía vigente de la RAE.
"""
from __future__ import annotations

from student_content_le_m1_c import E, L, M

OA18 = "LE1M OA 18"
MAT18 = "Este cuaderno, lápiz y las palabras y oraciones escritas en cada ejercicio. Si quieres, un diccionario (impreso o digital) para comprobar tus respuestas."

# ------------------------------------------------------------------ clase 1: tilde general
L(OA18, 1,
  MAT18,
  "Aprenderé a aplicar las reglas generales de tildación (palabras agudas, graves, esdrújulas y sobresdrújulas) para escribir con precisión y que el lector lea cada palabra como corresponde.",
  ["Sé separar una palabra en sílabas.", "Distingo vocales y consonantes."],
  ["Toda palabra tiene una sílaba que se pronuncia con más fuerza: la sílaba tónica. Según su lugar, la palabra es aguda (tónica en la última sílaba: ca-fé), grave (en la penúltima: ár-bol), esdrújula (en la antepenúltima: mú-si-ca) o sobresdrújula (antes de la antepenúltima: cuén-ta-se-lo). Para saber si lleva tilde, primero separa en sílabas, luego ubica la tónica y después aplica la regla.",
   "Las agudas llevan tilde si terminan en vocal, en n o en s: canción, café, compás. Las graves llevan tilde si terminan en una consonante distinta de n y s: árbol, lápiz, cárcel; si terminan en vocal, n o s no la llevan: casa, examen, mesas. Las esdrújulas y las sobresdrújulas siempre llevan tilde: teléfono, música, dígamelo.",
   "Los adverbios terminados en -mente conservan la tilde que tenía el adjetivo: fácil, fácilmente; rápida, rápidamente. La tilde no es adorno: cambia la lectura (célebre, celebre, celebré son tres palabras distintas). Revísala siempre al editar, porque un error de tilde puede dar otro sentido al texto."],
  [("sílaba tónica", "sílaba que se pronuncia con más fuerza"), ("aguda", "palabra con la sílaba tónica al final"), ("grave", "palabra con la sílaba tónica en la penúltima sílaba"), ("esdrújula", "palabra con la sílaba tónica en la antepenúltima sílaba"), ("sobresdrújula", "palabra con la tónica antes de la antepenúltima sílaba")],
  [("Tilde en una aguda", "¿Cómo se escribe «cancion»?",
    ["Separo en sílabas: can-ción.", "La tónica está al final: es aguda.", "Termina en n: lleva tilde."],
    "canción"),
   ("Tilde en una grave", "¿Cómo se escribe «arbol»?",
    ["Separo en sílabas: ar-bol.", "La tónica es la penúltima: es grave.", "Termina en l, que no es n ni s: lleva tilde."],
    "árbol")],
  [("Tildar todas las palabras que terminan en n o s.", "Se aplica la regla de las agudas a todas.", "Primero ubica la sílaba tónica: una grave terminada en n o s no lleva tilde."),
   ("Olvidar la tilde de las esdrújulas.", "Se confunde con las graves.", "Las esdrújulas siempre llevan tilde.")],
  ([M("¿Cuál es la sílaba tónica de «ventana»?", ["ta", "ven", "na"], 0, "En ven-ta-na se pronuncia más fuerte la penúltima sílaba."),
    M("«Lámpara» es una palabra…", ["esdrújula", "grave", "aguda"], 0, "Su tónica está en la antepenúltima sílaba: lám-pa-ra."),
    M("Elige la escritura correcta:", ["mesa", "mésa", "mesá"], 0, "Es grave terminada en vocal, por lo tanto no lleva tilde.")],
   [M("¿Por qué «camión» lleva tilde?", ["Es aguda y termina en n", "Es grave y termina en n", "Es grave y termina en vocal"], 0, "Las agudas terminadas en n, s o vocal se tildan."),
    M("¿Por qué «examen» no lleva tilde?", ["Es grave y termina en n", "Es aguda y termina en n", "Es esdrújula"], 0, "Las graves terminadas en n o s no se tildan."),
    M("¿Por qué «lápiz» lleva tilde?", ["Es grave y termina en z", "Es aguda y termina en z", "Es aguda y termina en vocal"], 0, "Las graves terminadas en consonante distinta de n o s se tildan.")],
   [M("Elige la escritura correcta:", ["teléfono", "telefóno", "telefono"], 0, "Es esdrújula: te-lé-fo-no."),
    M("Elige la escritura correcta:", ["cárcel", "carcel", "carcél"], 0, "Es grave terminada en l: cár-cel."),
    M("Elige la escritura correcta:", ["sofá", "sófa", "sofa"], 0, "Es aguda terminada en vocal: so-fá.")],
   [M("¿Por qué «azúcar» lleva tilde si termina en r?", ["Porque es grave y no termina en n ni s", "Porque es aguda", "Porque es sobresdrújula"], 0, "a-zú-car es grave terminada en consonante distinta de n o s."),
    M("¿Por qué «cuéntaselo» lleva tilde?", ["Porque es sobresdrújula", "Porque es grave", "Porque es aguda terminada en vocal"], 0, "Su sílaba tónica está antes de la antepenúltima: cuén-ta-se-lo.")],
   [E("Las palabras «tambien, jamas, cesped, lapiz, mesa, tomate» están escritas sin tilde. ¿Cuántas de ellas deben llevarla?", "4", "Llevan tilde también, jamás, césped y lápiz; mesa y tomate no."),
    M("¿Qué oración está bien tildada?", ["Mi hermano compró un balón y un lápiz.", "Mi hermano compro un balón y un lápiz.", "Mi hermano compró un balon y un lapiz."], 0, "Compró (aguda en vocal), balón (aguda en n) y lápiz (grave en z) llevan tilde.")]),
  [E("Un letrero dice: «Biblioteca. Prestamo de libros, horario de atencion, catalogo digital». ¿Cuántas palabras deben llevar tilde?", "3", "Préstamo y catálogo son esdrújulas; atención es aguda terminada en n.")],
  [E("¿Las esdrújulas siempre llevan tilde?", "Sí", "No tienen excepción en esta regla."),
   E("¿Una grave terminada en s lleva tilde?", "No", "Las graves se tildan solo si terminan en consonante distinta de n o s."),
   E("¿Hay que ubicar la sílaba tónica antes de tildar?", "Sí", "De ella depende la clasificación.")],
  ("Estas diez palabras están escritas sin tilde: corazon, agil, pelicula, jovenes, util, lider, examen, sabado, rapidamente, portatil. Escríbelas bien y anota, junto a cada una, si es aguda, grave, esdrújula o un adverbio en -mente. Una de ellas no lleva tilde: indica cuál y explica por qué.",
   "corazón (aguda), ágil (grave), película (esdrújula), jóvenes (esdrújula), útil (grave), líder (grave), examen (grave, no lleva tilde porque termina en n), sábado (esdrújula), rápidamente (adverbio: conserva la tilde de rápida), portátil (grave).",
   ["escribe bien las diez palabras", "las clasifica", "explica la que no lleva tilde"], ["lista corregida", "explicación breve"], ["tildar «examen»", "olvidar la tilde de rápidamente"], "Comprueba cada palabra en un diccionario."),
  "Busca en un texto que tengas en casa cinco palabras con tilde y clasifícalas.",
  "Escribe diez palabras esdrújulas que uses en tus asignaturas.")

# ------------------------------------------------------------------ clase 2: diptongo, hiato, tilde diacrítica
L(OA18, 2,
  MAT18,
  "Aprenderé a tildar diptongos e hiatos y a usar la tilde diacrítica (tú/tu, él/el, mí/mi, sí/si, té/te, más/mas, qué/que) para que las palabras no se confundan.",
  ["Sé clasificar una palabra en aguda, grave o esdrújula.", "Reconozco vocales abiertas (a, e, o) y cerradas (i, u)."],
  ["Un diptongo es la unión de dos vocales en una sola sílaba: una abierta con una cerrada (cuen-to, cau-sa) o dos cerradas distintas (ciu-dad, cui-da-do). Un hiato son dos vocales juntas que se pronuncian en sílabas distintas: dos abiertas (ca-er, po-e-ta) o una cerrada tónica con una abierta (dí-a, pa-ís, ba-úl). Si en el hiato la vocal cerrada es tónica, siempre lleva tilde, aunque la regla general no la pida.",
   "La tilde diacrítica distingue palabras iguales que cumplen funciones distintas. Con tilde: tú (pronombre: tú sabes), él (pronombre: se lo dije a él), mí (pronombre: es para mí), sí (afirmación o pronombre: sí, claro), té (infusión), más (cantidad), dé y sé (verbos dar y saber). Sin tilde: tu (posesivo: tu libro), el (artículo: el libro), mi (posesivo: mi libro), si (condición: si llueve), te (pronombre: te llamo), mas (pero), de y se.",
   "También llevan tilde qué, cuál, quién, cómo, dónde, cuándo y cuánto cuando preguntan o exclaman, incluso en preguntas indirectas: «Dime qué quieres comer». Sin tilde se usan para unir ideas: «El libro que quiero». Para decidir, prueba reemplazar: si puedes cambiar «tú» por «usted», lleva tilde; si puedes poner «mi libro» o «tu libro», es posesivo y no la lleva."],
  [("diptongo", "dos vocales en una misma sílaba"), ("hiato", "dos vocales juntas en sílabas distintas"), ("tilde diacrítica", "tilde que distingue dos palabras iguales con funciones distintas"), ("pronombre", "palabra que reemplaza a un nombre, como él o tú")],
  [("Hiato con tilde", "¿Cómo se escribe «pais»?",
    ["Lo separo: pa-ís.", "La vocal cerrada í es tónica y está junto a la abierta a: es un hiato.", "En el hiato con cerrada tónica siempre hay tilde."],
    "país"),
   ("Tilde diacrítica", "Corrige: «Tu sabes que tu perro es mas rapido que el».",
    ["El primer «tú» es pronombre: lleva tilde.", "«tu perro» es posesivo: sin tilde.", "«más» indica cantidad; «él» es pronombre; «rápido» es esdrújula."],
    "Tú sabes que tu perro es más rápido que él.")],
  [("Poner tilde a «tu» posesivo.", "Se piensa que todas las palabras de una tilde.", "Si puedes decir «mi», es posesivo y no lleva tilde."),
   ("No tildar «día» o «país».", "Se aplica la regla de los diptongos.", "En el hiato con cerrada tónica, la tilde es obligatoria.")],
  ([M("«Ciudad» tiene…", ["un diptongo", "un hiato", "una sobresdrújula"], 0, "ciu-dad: las dos vocales están en la misma sílaba."),
    M("«Día» tiene…", ["un hiato", "un diptongo", "una vocal abierta sola"], 0, "dí-a: la i tónica y la a están en sílabas distintas."),
    M("Elige la escritura correcta:", ["Me gusta el té caliente.", "Me gusta el te caliente.", "Me gusta él té caliente."], 0, "Aquí «té» nombra la infusión y se tilda.")],
   [M("¿Por qué «baúl» lleva tilde?", ["Porque tiene un hiato con vocal cerrada tónica", "Porque es grave terminada en vocal", "Porque tiene un diptongo"], 0, "ba-úl: la ú es cerrada, tónica y está junto a la a."),
    M("En «Se lo dije a él», ¿por qué «él» lleva tilde?", ["Porque es un pronombre personal", "Porque es un artículo", "Porque es un verbo"], 0, "Reemplaza a una persona; si fuera artículo no la llevaría."),
    M("«Quise ir, mas no pude». ¿Qué significa «mas» sin tilde?", ["pero", "cantidad", "otra vez"], 0, "Como conjunción equivale a «pero».")],
   [M("Completa: «No sé si ___ vendrás».", ["tú", "tu", "te"], 0, "Es el pronombre de segunda persona."),
    M("Completa: «Este regalo es para ___».", ["mí", "mi", "me"], 0, "Va después de «para» y es un pronombre."),
    M("Completa: «Dime ___ quieres comer».", ["qué", "que", "quién"], 0, "Es una pregunta indirecta sobre lo que se quiere comer.")],
   [M("En «Tu eres mi mejor amigo», ¿qué palabra necesita tilde?", ["tu", "mi", "mejor"], 0, "Es pronombre sujeto: «Tú eres»."),
    M("Elige la escritura correcta del nombre:", ["María", "Maria"], 0, "ma-rí-a es hiato con i cerrada tónica.")],
   [E("La oración «Tu sabes que el no vendra mas tarde» necesita correcciones. ¿Cuántas palabras llevan tilde en la oración corregida?", "4", "Corregida: «Tú sabes que él no vendrá más tarde»."),
    M("¿Cuál es la oración correcta?", ["Si me dices sí, voy contigo.", "Sí me dices si, voy contigo.", "Si me dices si, voy contigo."], 0, "El primer «si» es condicional; el segundo es afirmación.")]),
  [E("Un letrero de cafetería dice: «Ofrecemos te, cafe, jugo y mas postres». ¿Cuántas palabras deben llevar tilde?", "3", "Té, café y más llevan tilde.")],
  [E("¿«Mi» posesivo lleva tilde?", "No", "La tilde es para el pronombre «mí»."),
   E("¿«País» lleva tilde por ser un hiato con vocal cerrada tónica?", "Sí", "Esa es la regla del hiato."),
   E("¿Se puede escribir «qué» con tilde en una pregunta indirecta?", "Sí", "Por ejemplo: dime qué quieres.")],
  ("Corrige las tildes de este mensaje de ejemplo: «Hola, Camila. Tu sabes que el viernes hay prueba y yo si estudie, pero mi hermana me pregunto que hacer. Mi vecina dijo que si quiere, puede venir a estudiar con nosotras. Quieres te o cafe? Dime cuando puedes. Gracias, un abrazo». Escribe la versión corregida y subraya las palabras con tilde diacrítica.",
   "«Hola, Camila. Tú sabes que el viernes hay prueba y yo sí estudié, pero mi hermana me preguntó qué hacer. Mi vecina dijo que si quiere, puede venir a estudiar con nosotras. ¿Quieres té o café? Dime cuándo puedes. Gracias, un abrazo». Diacríticas: Tú, sí, qué, té, cuándo.",
   ["corrige tildes generales y diacríticas", "distingue «si» condicional de «sí»", "agrega los signos de interrogación"], ["mensaje corregido"], ["tildar «si» condicional", "olvidar «cuándo»"], "Lee el mensaje en voz alta y comprueba que la entonación coincida con las tildes."),
  "Anota diez palabras con hiato y diez con diptongo que encuentres en un libro.",
  "Escribe cinco oraciones usando tú/tu, él/el y mí/mi en cada una.")

# ------------------------------------------------------------------ clase 3: ortografía literal con reglas
L(OA18, 3,
  MAT18,
  "Aprenderé reglas de ortografía literal (b/v, g/j, h, c/s/z, ll/y, m antes de b y p, n antes de v) para escribir correctamente las palabras que sí tienen regla.",
  ["Sé distinguir verbos, sustantivos y adjetivos.", "Reconozco las terminaciones de un verbo."],
  ["Muchas dudas de ortografía se resuelven con una regla. Se escribe con b: los verbos terminados en -bir (escribir, recibir), excepto hervir, servir, vivir y sus derivados; el pretérito imperfecto de los verbos en -ar y de ir (cantaba, iba); y siempre después de m (ambos); además, antes de b y de p se escribe m (también, campo). Se escribe con v: la v después de n (invierno, envío); el presente de ir (voy, vas, va); el pretérito de estar, andar y tener (estuve, anduve, tuve); y los adjetivos en -ivo/-iva (activo, creativa).",
   "Con g se escriben los verbos terminados en -ger y -gir (proteger, elegir), excepto tejer y crujir, y las palabras con geo- (geografía) y las terminadas en -gen (origen). Con j se escriben las terminaciones -aje (viaje, mensaje) y -jero/-jera (extranjero), y formas como dijo, trajo y tradujo. La h va al inicio en las palabras que empiezan con hie-, hue- y hum- seguido de vocal (hielo, hueso, humedad).",
   "Con c o s: los sustantivos en -ción se relacionan con palabras terminadas en -to, -tor o -dor (acto, acción; educador, educación), y los en -sión con palabras en -so, -sor o -sivo (televisor, televisión; decisivo, decisión). Las palabras que terminan en z cambian a c en plural (lápiz, lápices). Los verbos terminados en -cer y -cir llevan c (nacer, conducir), y las palabras terminadas en -illo/-illa llevan ll (ardilla, castillo). Estas reglas tienen excepciones: ante la duda, consulta el diccionario."],
  [("regla ortográfica", "indicación que dice cómo se escribe un grupo de palabras"), ("excepción", "caso que no cumple una regla"), ("terminación", "letras finales de una palabra"), ("derivado", "palabra formada a partir de otra, como «sirvió» a partir de «servir»")],
  [("Aplicar una regla", "Completa con b o v: «escri__ir».",
    ["Es un verbo terminado en -bir.", "No es una de las excepciones (hervir, servir, vivir).", "Se escribe con b."],
    "escribir"),
   ("Usar el pretérito", "Completa con b o v: «Ayer estu__e en la biblioteca».",
    ["Es el pretérito del verbo estar.", "El pretérito de estar, andar y tener lleva v.", "Se escribe estuve."],
    "estuve")],
  [("Escribir «escrivir» con v.", "Se confunde con vivir.", "Los verbos en -bir llevan b, salvo hervir, servir y vivir."),
   ("Escribir «lápizes».", "Se agrega -es sin cambiar la z.", "La z cambia a c: lápices.")],
  ([M("Completa: «prote__er». ¿Cuál letra falta?", ["g", "j", "h"], 0, "Los verbos terminados en -ger llevan g: proteger."),
    M("¿Cómo se escribe correctamente?", ["hielo", "ielo", "jielo"], 0, "Las palabras que empiezan con hie- llevan h."),
    M("¿Cómo se escribe el imperfecto de cantar en «Mi abuela ___ en el coro»?", ["cantaba", "cantava", "cantába"], 0, "El imperfecto de los verbos en -ar se escribe con b.")],
   [M("¿Cuál de estos verbos terminados en -ir se escribe con v?", ["servir", "escribir", "recibir"], 0, "Servir es una excepción a la regla de -bir."),
    M("Completa: «televi__ión».", ["s", "c", "z"], 0, "Se relaciona con «televisor», que termina en -sor."),
    M("¿Cómo se escribe correctamente el plural de «lápiz»?", ["lápices", "lápizes", "lápises"], 0, "La z cambia a c ante e.")],
   [M("Completa: «El equipa__e es pesado».", ["j", "g", "x"], 0, "La terminación -aje se escribe con j."),
    M("Completa: «Ardi__a» (el animal de cola esponjada).", ["ll", "y", "ñ"], 0, "Las palabras en -illa se escriben con ll."),
    M("¿Cuál palabra sigue la regla de la n antes de v?", ["invierno", "imbierno", "inbierno"], 0, "Después de n se escribe v: invierno.")],
   [M("¿Qué regla justifica la m de «también»?", ["Antes de b se escribe m", "Antes de b se escribe n", "Antes de t se escribe m"], 0, "La m aparece antes de b y p."),
    M("¿Por qué «voy» y «vas» se escriben con v?", ["Son formas del presente del verbo ir", "Son verbos en -bir", "Terminan en -aje"], 0, "El presente de ir lleva v.")],
   [E("«El estudiante recivió un mensage y escrivió su respuesta». ¿Cuántas palabras tienen errores de ortografía literal?", "3", "Recibió, mensaje y escribió son las tres correcciones."),
    M("¿Cuál oración está bien escrita?", ["Mi hermana es muy creativa y activa en el taller.", "Mi hermana es muy creatiba y activa en el taller.", "Mi hermana es muy creativa y actíba en el taller."], 0, "Los adjetivos en -ivo/-iva se escriben con v.")]),
  [M("En el mensaje «El inbierno llegó y mi familia viajó al sur», ¿qué palabra tiene un error?", ["inbierno", "viajó", "familia"], 0, "Después de n se escribe v: invierno.")],
  [E("¿Los sustantivos terminados en -aje se escriben con j?", "Sí", "Es una regla de la terminación."),
   E("¿Existen excepciones a las reglas ortográficas?", "Sí", "Por ejemplo, servir lleva v."),
   E("¿Se escribe «también» con n antes de b?", "No", "Antes de b se escribe m.")],
  ("Completa con la letra correcta y escribe la regla que usaste en cada caso: 1) reci__ir ; 2) __ielo ; 3) mensa__e ; 4) lápi__es ; 5) ardi__a ; 6) in__ierno ; 7) pretérito de «tener», primera persona: tu__e ; 8) protec__ión ; 9) ele__ir ; 10) acti__a.",
   "1) recibir (verbo en -bir, no es excepción). 2) hielo (hie- lleva h). 3) mensaje (-aje). 4) lápices (z cambia a c). 5) ardilla (-illa). 6) invierno (después de n, v). 7) tuve (pretérito de tener). 8) protección (-ción, relacionada con «protector»). 9) elegir (verbo en -gir, no es excepción). 10) activa (-iva).",
   ["completa las diez palabras", "nombra la regla de cada una", "distingue letras de sonido parecido (b/v, g/j, c/s)"], ["lista completa con reglas"], ["escribir «recivir»", "no justificar la regla"], "Comprueba cada palabra en el diccionario."),
  "Escribe un listado de diez palabras con h y diez con j que uses en clase.",
  "Inventa una regla fácil para recordar si «servir» lleva b o v y compártela.")

# ------------------------------------------------------------------ clase 4: palabras sin regla y homófonos
L(OA18, 4,
  MAT18,
  "Aprenderé a escribir palabras cuya ortografía no depende de reglas, a distinguir homófonos y a verificar la grafía en el diccionario.",
  ["Conozco las reglas de b/v, g/j, h y c/s/z.", "Sé buscar una palabra por orden alfabético."],
  ["Hay palabras que no se pueden escribir por regla: se aprenden con la lectura, la práctica y la consulta del diccionario. Un caso frecuente son los homófonos, palabras que suenan igual, pero se escriben distinto y significan algo diferente: hecho (de hacer) y echo (de echar); tubo (cilindro hueco) y tuvo (de tener); cayó (de caer) y calló (de callar); vaya (de ir), valla (cerca) y baya (fruto pequeño); hola (saludo) y ola (del mar); asta (palo de una bandera) y hasta (preposición); grabar (registrar o marcar) y gravar (poner un impuesto); bello (hermoso) y vello (pelo fino del cuerpo).",
   "Para elegir, usa el contexto y la familia de palabras. «Hecho» se relaciona con «hacer»; «echo», con «echar». Con «a ver / haber»: «a ver» expresa mirar o comprobar («a ver si llegó»); «haber» es el verbo (debe haber pan). Con «sino / si no»: «sino» opone («no quiero té, sino café»); «si no» es una condición negativa («si no estudias, no aprobarás»).",
   "También hay tres formas con «porque». «Porque» responde a una pregunta y expresa causa. «Por qué» se usa para preguntar (¿por qué llegaste tarde?). «Porqué» es un sustantivo con artículo: «el porqué de la decisión». Cuando dudes, busca la palabra en el diccionario: lee su definición y los ejemplos, y comprueba que calce con tu oración."],
  [("homófonos", "palabras que suenan igual y se escriben distinto"), ("familia de palabras", "palabras que comparten una misma raíz"), ("diccionario", "libro o sitio donde se explica el significado y la ortografía de las palabras"), ("contexto", "palabras que rodean a otra y ayudan a entenderla")],
  [("Elegir el homófono", "Completa: «Ya he ___ la tarea» (hecho / echo).",
    ["La palabra se relaciona con el verbo hacer.", "He + participio: he hecho.", "Se escribe hecho."],
    "hecho"),
   ("Elegir porque o por qué", "Completa: «Pregunté ___ llegaste tarde» (porque / por qué).",
    ["Es una pregunta indirecta.", "Las preguntas se escriben con por qué separado.", "Se escribe por qué."],
    "por qué")],
  [("Escribir «haber si llegó» para expresar comprobar.", "Se confunden los sonidos.", "Si puedes reemplazar por «mirar», escribe «a ver»."),
   ("Escribir «porque» al preguntar.", "Se confunde la causa con la pregunta.", "Para preguntar, escribe por qué separado y con tilde.")],
  ([M("Completa: «El agua pasa por el ___ de goma».", ["tubo", "tuvo", "tuvó"], 0, "Es un objeto cilíndrico, no una forma del verbo tener."),
    M("Completa: «Voy a ___ si hay pan en la panadería».", ["ver", "haber", "aber"], 0, "La expresión «a ver» significa mirar o comprobar."),
    M("Completa: «Una ___ gigante llegó a la orilla».", ["ola", "hola", "ora"], 0, "La ola es el movimiento del agua; hola es un saludo.")],
   [M("¿Con qué verbo se relaciona «echo» en «Yo echo agua al vaso»?", ["echar", "hacer", "hechizar"], 0, "Significa arrojar o poner: del verbo echar."),
    M("Completa: «El niño se ___ de la bicicleta».", ["cayó", "calló", "cayo"], 0, "Es una forma del verbo caer."),
    M("Completa: «La bandera sube por el ___».", ["asta", "hasta", "aste"], 0, "El asta es el palo; hasta es una preposición.")],
   [M("Completa: «No viajaré ___ me duele el pie».", ["porque", "por qué", "porqué"], 0, "Expresa la causa de no viajar."),
    M("Completa: «¿___ no viniste a clases?»", ["Por qué", "Porque", "Porqué"], 0, "Es una pregunta directa."),
    M("Completa: «Nadie sabe el ___ de su decisión».", ["porqué", "porque", "por que"], 0, "Es un sustantivo precedido por el artículo «el».")],
   [M("Completa: «No quiero té, ___ café».", ["sino", "si no", "sinó"], 0, "Se opone una cosa a otra."),
    M("Completa: «Si ___ estudias, no aprobarás».", ["no", "sino", "tan"], 0, "Hace falta la condición negativa «si no»."),
    M("Elige el verbo ir: «Espero que ___ a la fiesta».", ["vaya", "valla", "baya"], 0, "Es una forma del verbo ir.")],
   [M("¿Cuál es la oración correcta?", ["A ver si vienes mañana.", "Haber si vienes mañana.", "Aver si vienes mañana."], 0, "«A ver» expresa comprobar o esperar."),
    M("En «Quiero ___ un video de la obra», ¿cuál se usa?", ["grabar", "gravar"], 0, "Se quiere registrar imágenes, no cobrar un impuesto.")]),
  [M("Un estudiante duda entre «bello» y «vello». Quiere decir que el paisaje es hermoso. ¿Qué escribe?", ["El paisaje es bello.", "El paisaje es vello."], 0, "«Bello» significa hermoso; «vello» es pelo fino del cuerpo.")],
  [E("¿Los homófonos suenan igual?", "Sí", "Se diferencian por su escritura y significado."),
   E("¿«Porqué» con artículo es un sustantivo?", "Sí", "Por ejemplo: el porqué."),
   E("¿Puede un diccionario ayudar a elegir entre dos palabras?", "Sí", "Aclara el significado de cada una.")],
  ("Completa el texto de ejemplo con las palabras entre paréntesis: «Anoche (hubo/ubo) una tormenta y el agua (cayó/calló) por el (tubo/tuvo) de la casa. El vecino preguntó (porque/por qué) el techo goteaba, y el conserje dijo que (a ver/haber) si lo reparaban. No fue un accidente, (sino/si no) un susto». Elige en cada caso y explica en una línea qué te ayudó (contexto, familia de palabras o diccionario).",
   "«Anoche hubo una tormenta y el agua cayó por el tubo de la casa. El vecino preguntó por qué el techo goteaba, y el conserje dijo que a ver si lo reparaban. No fue un accidente, sino un susto». hubo: verbo haber; cayó: verbo caer; tubo: cilindro; por qué: pregunta; a ver: comprobar; sino: oposición.",
   ["elige las seis formas correctas", "explica una pista por cada una", "usa contexto o familia de palabras"], ["texto completado", "explicaciones breves"], ["confundir a ver / haber", "escribir «porque» al preguntar"], "Comprueba dos elecciones en un diccionario y anota qué definición leíste."),
  "Anota diez palabras que te cuesten y búscalas en un diccionario.",
  "Escribe tres oraciones con pares de homófonos distintos a los vistos.")

# ------------------------------------------------------------------ clase 5: punto, coma, punto y coma, dos puntos
L(OA18, 5,
  MAT18,
  "Aprenderé a usar punto, coma, punto y coma y dos puntos para organizar mis ideas y evitar ambigüedades de lectura.",
  ["Sé reconocer una oración.", "Distingo sujeto y verbo."],
  ["El punto cierra un enunciado: el punto y seguido separa oraciones dentro de un párrafo; el punto y aparte cierra el párrafo; el punto final cierra el texto. La coma marca pausas dentro de la oración. Se usa: para separar los elementos de una enumeración (sin coma antes de y, o, ni): «Compré lápices, gomas y cuadernos»; para llamar a alguien (vocativo): «Mateo, ven a comer»; para encerrar una aclaración o aposición: «Mi tía Rosa, la menor, vive en Osorno»; después de conectores: «Sin embargo, llegó tarde»; antes de «pero» o «aunque»; y después de un complemento antepuesto: «Cuando llegué, ya comían».",
   "No se escribe coma entre sujeto y verbo: «Los estudiantes estudian mucho», no «Los estudiantes, estudian mucho». El punto y coma separa elementos de una enumeración que ya tiene comas («Fui a Arica, a Iquique y a Antofagasta; mi hermana, a Valdivia y a Osorno») y puede ir antes de «sin embargo» o «por lo tanto» en oraciones largas.",
   "Los dos puntos anuncian: una enumeración («Traigan lo siguiente: lápiz, cuaderno y regla»), una cita textual («Mi abuela decía: «Más vale tarde que nunca»») o el saludo de una carta («Estimada profesora:»). También sirven para explicar o concluir lo anterior: «Faltó algo importante: el permiso». Una coma mal puesta cambia el sentido: «No quiero ir» no significa lo mismo que «No, quiero ir»."],
  [("vocativo", "palabra con la que se llama o se dirige uno a alguien"), ("aposición", "frase que explica o aclara a un sustantivo"), ("enumeración", "lista de elementos de un mismo tipo"), ("conector", "palabra que une ideas, como «sin embargo»")],
  [("Coma en enumeración", "Puntúa: «Compré pan leche huevos y queso».",
    ["Hay cuatro elementos enumerados.", "Se separan con comas, salvo antes de «y».", "Escribo: Compré pan, leche, huevos y queso."],
    "Compré pan, leche, huevos y queso."),
   ("Coma en vocativo", "Puntúa: «Camila ven acá».",
    ["«Camila» es la persona a la que se llama.", "El vocativo se separa con coma.", "Escribo: Camila, ven acá."],
    "Camila, ven acá.")],
  [("Poner coma entre sujeto y verbo.", "Se marca una pausa al hablar.", "No se separa el sujeto del verbo con coma."),
   ("Escribir coma antes de la última «y» de una enumeración simple.", "Se copia la costumbre de otros idiomas.", "Antes de y, o, ni no se usa coma en enumeraciones.")],
  ([M("¿Cuál está bien puntuada?", ["Mateo, ven a comer.", "Mateo ven, a comer.", "Mateo ven a, comer."], 0, "El vocativo se separa con coma."),
    E("«Trajimos manzanas peras uvas y naranjas». ¿Cuántas comas necesita en la versión correcta?", "2", "Las comas separan los elementos, pero no va coma antes de la «y» final: manzanas, peras, uvas y naranjas."),
    M("¿Qué signo anuncia una lista?", ["los dos puntos", "el punto y seguido", "la coma"], 0, "Los dos puntos preparan al lector para una enumeración.")],
   [M("¿Por qué se pone coma en «Sin embargo, llegó»?", ["Porque «sin embargo» es un conector", "Porque la oración es larga", "Porque es una lista"], 0, "Los conectores al inicio se separan con coma."),
    M("¿Cuál oración está bien puntuada?", ["Los estudiantes estudian mucho.", "Los estudiantes, estudian mucho."], 0, "No se separa el sujeto del verbo."),
    M("En «Fui a Arica, a Iquique y a Antofagasta; mi hermana, a Valdivia y a Osorno», ¿qué función cumple el punto y coma?", ["separa dos partes que ya tienen comas", "cierra el párrafo", "anuncia una cita"], 0, "Ordena dos enumeraciones que contienen comas.")],
   [M("Elige cómo se escribe el saludo de una carta:", ["Querida Ana:", "Querida Ana;", "Querida Ana…"], 0, "Los dos puntos cierran el saludo de una carta."),
    M("Elige la oración bien puntuada:", ["Mi abuela decía: «Más vale tarde que nunca».", "Mi abuela decía, «Más vale tarde que nunca».", "Mi abuela decía «Más vale tarde que nunca»;"], 0, "Los dos puntos introducen una cita."),
    M("Elige la oración con la aposición bien puntuada:", ["Mi tía Rosa, la menor de mis tías, vive en Osorno.", "Mi tía Rosa la menor de mis tías, vive en Osorno.", "Mi tía Rosa, la menor de mis tías vive en Osorno."], 0, "La aposición va entre dos comas.")],
   [M("¿En cuál enumeración está bien puesta la coma?", ["Compré lápices, gomas y cuadernos.", "Compré lápices, gomas, y cuadernos."], 0, "No se escribe coma antes de la «y» final."),
    M("¿Qué frase expresa que la persona no desea ir?", ["No quiero ir.", "No, quiero ir."], 0, "La coma en la segunda frase cambia el sentido: responde «no» y luego dice que quiere ir.")],
   [M("¿Cuál es la puntuación correcta?", ["Pedro, sin embargo, llegó tarde.", "Pedro sin embargo, llegó tarde.", "Pedro, sin embargo llegó tarde."], 0, "El conector intercalado va entre comas."),
    E("«Cuando terminó la clase Valeria mi mejor amiga me esperó en la puerta». ¿Cuántas comas necesita?", "3", "Una tras «clase» y dos para la aposición «mi mejor amiga».")]),
  [M("Un aviso dice: «Traigan lo siguiente lápices cuaderno y regla». ¿Cuál es la versión bien puntuada?", ["Traigan lo siguiente: lápices, cuaderno y regla.", "Traigan lo siguiente, lápices; cuaderno y regla.", "Traigan: lo siguiente lápices, cuaderno y regla."], 0, "Los dos puntos anuncian la lista y las comas la separan.")],
  [E("¿Se separa con coma el vocativo?", "Sí", "Por ejemplo: Mateo, ven."),
   E("¿Se pone coma antes de la última «y» de una enumeración simple?", "No", "Se evita en estos casos."),
   E("¿Los dos puntos pueden anunciar una cita?", "Sí", "Se usan antes de una cita textual.")],
  ("Puntúa este texto de ejemplo (puedes usar punto, coma, punto y coma y dos puntos): «Estimado director. Los estudiantes de primero medio queremos proponer tres actividades una feria del libro una jornada de limpieza y un campeonato de ajedrez. Sin embargo necesitamos su autorización. Mi compañera Ema la presidenta del curso dijo que todos están dispuestos a ayudar. Atentamente Primero Medio B». Explica en una línea el uso de tres de los signos que pusiste.",
   "«Estimado director: Los estudiantes de primero medio queremos proponer tres actividades: una feria del libro, una jornada de limpieza y un campeonato de ajedrez. Sin embargo, necesitamos su autorización. Mi compañera Ema, la presidenta del curso, dijo que todos están dispuestos a ayudar. Atentamente, Primero Medio B». Dos puntos tras el saludo y antes de la lista; comas en la enumeración, tras «Sin embargo» y en la aposición.",
   ["puntúa correctamente la enumeración", "separa la aposición y el conector", "explica tres usos"], ["texto puntuado", "tres explicaciones"], ["coma entre sujeto y verbo", "olvidar los dos puntos del saludo"], "Lee el texto en voz alta y comprueba que las pausas coincidan con tus signos."),
  "Subraya en un texto tuyo las comas que crees que sobran y justifica por qué.",
  "Escribe un párrafo con una enumeración, una aposición, un conector y una cita, bien puntuados.")

# ------------------------------------------------------------------ clase 6: raya, paréntesis, puntos suspensivos, comillas
L(OA18, 6,
  MAT18,
  "Aprenderé a usar raya, paréntesis, puntos suspensivos y comillas, y a editar un texto completo para que el lector lo comprenda sin esfuerzo.",
  ["Sé usar punto, coma y dos puntos.", "Distingo la voz del narrador de la voz de un personaje."],
  ["La raya (—) abre cada intervención en un diálogo y encierra los comentarios del narrador. Se escribe pegada a la palabra siguiente: «—¿Vienes? —preguntó Ana». Si el narrador interrumpe y el personaje sigue, el comentario va entre rayas: «—Sí —respondió Luis—, pero llegaré tarde». Si después del comentario va un punto, este se escribe después de la raya de cierre: «—Vamos —dijo Ana—. Se hace tarde». No la confundas con el guion corto (-), que une palabras.",
   "Los paréntesis encierran aclaraciones, datos o siglas: «La RAE (Real Academia Española) publica el diccionario». El signo de puntuación se escribe después del paréntesis de cierre. Los puntos suspensivos son siempre tres (…) y expresan duda, suspenso, interrupción o una enumeración abierta («lunes, martes, miércoles…»); no se combinan con «etc.». Las comillas (« ») enmarcan citas textuales breves, títulos de poemas o artículos, palabras con sentido irónico o especial, y términos de otro idioma.",
   "Al editar, lee el texto como lo haría un lector que no te conoce: ¿se distingue quién habla?, ¿las aclaraciones están en su lugar?, ¿las pausas de suspenso tienen una razón? Revisa también que cada signo de apertura tenga su cierre: no deben quedar paréntesis, comillas ni rayas abiertas. Un buen texto puntuado se lee sin que tengas que adivinar."],
  [("raya", "signo largo (—) que marca diálogos e incisos"), ("paréntesis", "signos ( ) que encierran una aclaración"), ("puntos suspensivos", "tres puntos seguidos que marcan duda, suspenso o enumeración abierta"), ("comillas", "signos « » que encierran citas, títulos o palabras con sentido especial")],
  [("Puntuar un diálogo", "Puntúa: «Vienes preguntó Ana. Sí respondió Luis pero llegaré tarde».",
    ["Cada intervención empieza con raya.", "Los comentarios del narrador van entre rayas o tras una raya.", "Escribo: —¿Vienes? —preguntó Ana. —Sí —respondió Luis—, pero llegaré tarde."],
    "—¿Vienes? —preguntó Ana. —Sí —respondió Luis—, pero llegaré tarde."),
   ("Usar paréntesis", "Puntúa: «La RAE Real Academia Española publica el diccionario».",
    ["«Real Academia Española» aclara la sigla.", "Las aclaraciones van entre paréntesis.", "Escribo: La RAE (Real Academia Española) publica el diccionario."],
    "La RAE (Real Academia Española) publica el diccionario.")],
  [("Usar guion corto (-) en lugar de raya en un diálogo.", "Se escribe con el teclado sin pensar.", "La raya (—) es más larga y se escribe pegada a la palabra."),
   ("Escribir más de tres puntos o usar «etc.…».", "Se cree que más puntos significan más suspenso.", "Los puntos suspensivos son tres y no se combinan con «etc.».")],
  ([M("¿Qué signo introduce la intervención de un personaje en un diálogo narrativo?", ["la raya", "el paréntesis", "las comillas"], 0, "Cada intervención se abre con raya."),
    M("¿Cuántos puntos tienen los puntos suspensivos?", ["tres", "dos", "cuatro"], 0, "Siempre son tres."),
    M("¿Qué signos encierran una aclaración como «(Organización de las Naciones Unidas)»?", ["los paréntesis", "las rayas", "los dos puntos"], 0, "Los paréntesis marcan datos aclaratorios.")],
   [M("En «Compré pan, leche, huevos…», ¿para qué sirven los puntos suspensivos?", ["indican que la enumeración continúa", "indican una pregunta", "cierran el párrafo"], 0, "Dejan abierta la lista."),
    M("En «Mi hermana leyó el poema “Nubes de abril”», ¿qué función cumplen las comillas?", ["marcan el título de un poema", "indican una cita de un diálogo", "indican duda"], 0, "Los títulos de poemas y artículos se escriben entre comillas."),
    M("En «—Ven —dijo Ana—. Te espero.», ¿cuál es el comentario del narrador?", ["dijo Ana", "Te espero", "Ven"], 0, "Es la parte entre rayas que aclara quién habla.")],
   [M("¿Cuál diálogo está bien escrito?", ["—¿Vamos al cine? —preguntó Mateo.", "- ¿Vamos al cine? - preguntó Mateo.", "«¿Vamos al cine?» preguntó Mateo."], 0, "Usa raya pegada y el comentario del narrador."),
    M("¿Dónde va el punto?", ["Leí un libro (en realidad, dos). Luego dormí", "Leí un libro (en realidad, dos.) Luego dormí"], 0, "El punto va después del paréntesis de cierre."),
    M("¿Cuál usa bien los puntos suspensivos en una enumeración abierta?", ["Vimos leones, tigres, elefantes…", "Vimos leones, tigres, elefantes etc…", "Vimos leones, tigres, elefantes....."], 0, "Los tres puntos bastan y no se combinan con «etc.».")],
   [M("En «Dijo que iría… quizás.», ¿qué expresan los puntos suspensivos?", ["duda o vacilación", "una enumeración", "una cita"], 0, "La pausa muestra que la persona no está segura."),
    M("En «Mi hermano, el “experto”, rompió el control», ¿qué sentido dan las comillas a “experto”?", ["irónico: no lo es en realidad", "elogioso: es un gran experto", "neutral: es un título"], 0, "El contexto (rompió el control) indica ironía.")],
   [E("En «—Llegaste temprano —comentó Ana—. ¿Quieres pan?», ¿cuántas rayas hay?", "3", "Una al inicio y dos que encierran el comentario del narrador."),
    M("¿Cuál cita está bien puntuada?", ["El letrero decía «Prohibido pasar.» Nadie entró", "El letrero decía: «Prohibido pasar». Nadie entró", "El letrero decía; «Prohibido pasar» Nadie entró"], 1, "Los dos puntos introducen la cita y el punto va después de las comillas.")]),
  [M("Un cuento escolar contiene: La profesora dijo ven a la pizarra y yo respondí ya voy. ¿Cuál es la versión bien puntuada?", ["—Ven a la pizarra —dijo la profesora. —Ya voy —respondí yo.", "- Ven a la pizarra - dijo la profesora. - Ya voy - respondí yo.", "«Ven a la pizarra», dijo la profesora, «ya voy» respondí yo."], 0, "Usa rayas pegadas y separa las dos intervenciones.")],
  [E("¿Los puntos suspensivos son siempre tres?", "Sí", "Más puntos no se usan en español."),
   E("¿Un paréntesis abierto debe cerrarse?", "Sí", "Todo signo doble debe tener su cierre."),
   E("¿La raya es igual que el guion corto?", "No", "Son signos de distinta longitud y función.")],
  ("Edita este texto de ejemplo, que no tiene signos: «Ayer en la feria del colegio mi amigo Tomás vendía libros usados cuentos novelas cómics La profesora de Historia le preguntó cuánto cuesta este libro Tomás dudó bueno creo que mil pesos La profesora sonrió y leyó el título del cuento Noche de lluvia en voz alta». Agrega comas y dos puntos donde corresponda, rayas para el diálogo (puedes escribirlo en líneas separadas), un paréntesis para aclarar «cómics (historietas)», puntos suspensivos para la duda, y comillas para el título.",
   "«Ayer, en la feria del colegio, mi amigo Tomás vendía libros usados: cuentos, novelas, cómics (historietas). La profesora de Historia le preguntó: —¿Cuánto cuesta este libro? —Bueno… —dudó Tomás—, creo que mil pesos. La profesora sonrió y leyó el título del cuento: «Noche de lluvia», en voz alta». Se distingue quién habla, se aclara entre paréntesis y la duda se marca con puntos suspensivos.",
   ["usa raya en el diálogo", "usa comillas para el título", "usa puntos suspensivos con sentido y cierra todos los signos"], ["texto editado"], ["usar guion corto", "dejar signos sin cierre"], "Pide a otra persona que lea el diálogo con voces distintas para comprobar que se entiende quién habla."),
  "Copia un diálogo de un libro que tengas y marca cada raya, cada comentario del narrador y los signos de cierre.",
  "Escribe un diálogo de seis intervenciones con comentarios del narrador, paréntesis, puntos suspensivos y comillas bien usados.")
